-- name: platform__workers_reconcilewarmruntime_1 :one
SELECT a.ref,ar.stable_key,a.name,a.purpose,ar.core_prompt_revision,ar.owner_instructions,ar.runtime_state,ar.runtime_revision,ar.desired_runtime_revision,ar.system_session_ref,ar.resource_limits,ar.last_heartbeat_at,ar.version,ar.updated_at,i.ref,i.digest,i.content,COALESCE(ar.warm_instance_ref,''),a.runtime_key,rp.runtime_revision,rp.provider,rp.model FROM control_plane.assistant_runtime ar JOIN control_plane.agents a ON a.id=ar.agent_id JOIN control_plane.instruction_versions i ON i.ref=ar.core_prompt_ref JOIN control_plane.runtime_profiles rp ON rp.stable_key=a.runtime_key WHERE ar.organization_id=$1::uuid FOR UPDATE
